#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    std::string lastNonEmptyString(std::string s) {
        std::vector<int> count(26, 0);
        std::vector<int> last(26, -1);
        int mx = 0;
        for (size_t i = 0; i < s.size(); ++i) {
            int c = s[i] - 'a';
            count[c]++;
            last[c] = i;
            mx = std::max(mx, count[c]);
        }
        std::vector<std::pair<int, char>> survivors;
        for (int c = 0; c < 26; ++c) {
            if (count[c] == mx) {
                survivors.push_back({last[c], (char)('a' + c)});
            }
        }
        std::sort(survivors.begin(), survivors.end());
        std::string ans = "";
        for (const auto& p : survivors) ans += p.second;
        return ans;
    }
};

import java.util.*;

class Solution {
    public String lastNonEmptyString(String s) {
        int[] count = new int[26];
        int[] last = new int[26];
        int mx = 0;
        for (int i = 0; i < s.length(); ++i) {
            int c = s.charAt(i) - 'a';
            count[c]++;
            last[c] = i;
            mx = Math.max(mx, count[c]);
        }
        List<int[]> survivors = new ArrayList<>();
        for (int c = 0; c < 26; ++c) {
            if (count[c] == mx) survivors.add(new int[]{last[c], c});
        }
        survivors.sort(Comparator.comparingInt(a -> a[0]));
        StringBuilder sb = new StringBuilder();
        for (int[] p : survivors) sb.append((char)('a' + p[1]));
        return sb.toString();
    }
}

var lastNonEmptyString = function(s) {
    const count = new Array(26).fill(0);
    const last = new Array(26).fill(-1);
    let mx = 0;
    for (let i = 0; i < s.length; ++i) {
        const c = s.charCodeAt(i) - 97;
        count[c]++;
        last[c] = i;
        mx = Math.max(mx, count[c]);
    }
    const survivors = [];
    for (let c = 0; c < 26; ++c) {
        if (count[c] === mx) survivors.push({ pos: last[c], ch: String.fromCharCode(97 + c) });
    }
    survivors.sort((a, b) => a.pos - b.pos);
    return survivors.map(x => x.ch).join('');
};
